use deadlib_lua::{Value, compile_named};
use deadsync_song_lua::{
    self as song, SongLuaCompileContext,
    rust_engine::{RustSongRuntime, test_support},
};
use std::path::Path;

fn context() -> SongLuaCompileContext {
    SongLuaCompileContext::new(Path::new("."), "Player state migration")
}
fn execute(runtime: &mut RustSongRuntime, source: &str) -> Vec<Value> {
    runtime
        .vm_mut()
        .execute(&compile_named(source.as_bytes(), b"@/fixture/player-state.lua").unwrap())
        .unwrap_or_else(|e| panic!("{source}\n{e:?}"))
        .to_vec()
}
#[derive(Debug, PartialEq)]
enum Scalar {
    Nil,
    Boolean(bool),
    Number(u64),
    String(Vec<u8>),
}
fn number(n: f64) -> Scalar {
    Scalar::Number(if n.is_nan() {
        f64::NAN.to_bits()
    } else {
        n.to_bits()
    })
}
struct Pair {
    legacy: mlua::Lua,
    rust: RustSongRuntime,
}
impl Pair {
    fn new(context: &SongLuaCompileContext) -> Self {
        let legacy = mlua::Lua::new();
        if context.live {
            test_support::set_legacy_live_clock(&legacy, true);
        }
        song::install_default_stdlib_compat(&legacy, &context.song_dir).unwrap();
        song::install_game_state_globals(&legacy, context).unwrap();
        legacy
            .globals()
            .set("SongUtil", song::create_song_util_table(&legacy).unwrap())
            .unwrap();
        legacy
            .globals()
            .set(song::SONG_LUA_SIDE_EFFECT_COUNT_KEY, 0)
            .unwrap();
        test_support::expose_legacy_catalog(&legacy).unwrap();
        test_support::expose_legacy_option_operations(&legacy).unwrap();
        song::install_manager_globals(&legacy, context).unwrap();
        let mut rust = RustSongRuntime::new(context).unwrap();
        test_support::expose_catalog(&mut rust).unwrap();
        let mut pair = Self { legacy, rust };
        pair.compare(SNAPSHOT);
        pair.compare(SETUP);
        pair
    }
    fn compare(&mut self, source: &str) {
        let expected: mlua::MultiValue = self
            .legacy
            .load(source)
            .eval()
            .unwrap_or_else(|e| panic!("{source}\n{e}"));
        let expected: Vec<_> = expected
            .into_iter()
            .map(|v| match v {
                mlua::Value::Nil => Scalar::Nil,
                mlua::Value::Boolean(b) => Scalar::Boolean(b),
                mlua::Value::Integer(n) => number(n as f64),
                mlua::Value::Number(n) => number(n),
                mlua::Value::String(s) => Scalar::String(s.as_bytes().to_vec()),
                other => panic!("scalar expected: {other:?}"),
            })
            .collect();
        let actual: Vec<_> = execute(&mut self.rust, source)
            .into_iter()
            .map(|v| match v {
                Value::Nil => Scalar::Nil,
                Value::Boolean(b) => Scalar::Boolean(b),
                Value::Number(n) => number(n),
                Value::String(id) => {
                    Scalar::String(self.rust.vm_mut().string_bytes(id).unwrap().to_vec())
                }
                other => panic!("scalar expected: {other:?}"),
            })
            .collect();
        if actual != expected {
            for (a, b) in actual.iter().zip(&expected) {
                if let (Scalar::String(a), Scalar::String(b)) = (a, b) {
                    if a != b {
                        let i = a
                            .iter()
                            .zip(b)
                            .position(|(a, b)| a != b)
                            .unwrap_or(a.len().min(b.len()));
                        panic!(
                            "snapshot mismatch at {i}: actual {:?}, expected {:?}",
                            String::from_utf8_lossy(&a[i.saturating_sub(60)..a.len().min(i + 180)]),
                            String::from_utf8_lossy(&b[i.saturating_sub(60)..b.len().min(i + 180)])
                        );
                    }
                }
            }
            assert_eq!(actual, expected, "{source}");
        }
    }
}

const SNAPSHOT: &str = r#"
function snapshot(v)
    local kind=type(v)
    if kind=='table' then
        local entries={}
        for k,value in pairs(v) do entries[#entries+1]=snapshot(k)..'='..snapshot(value) end
        table.sort(entries);return '{'..table.concat(entries,';')..'}'
    elseif kind=='string' then return 's'..#v..':'..v
    elseif kind=='number' then return v~=v and 'nan' or string.format('%.17g',v)
    elseif kind=='boolean' then return tostring(v)
    else return kind end
end
"#;

const SETUP: &str = r#"
function pack(...) return {n=select('#',...),...} end
function outcome(owner,fn,...)
    local r=pack(pcall(fn,...))
    if not r[1] then return {ok=false} end
    for i=2,r.n do if r[i]==owner then r[i]='owner' end end
    return r
end
states=catalog.player_states
groups=catalog.option_operations
players=catalog.player_options
songs=catalog.song_options
function all_options() return snapshot({players,songs}) end
options=players[1][3]
NOTESKIN={DoesNoteSkinExist=function(self,name) return name=='cel' or name=='metal' or name=='my skin' end,
GetNoteSkinNames=function()return {'cel','metal','my skin'}end}
"#;

