use deadlib_lua::{Value, compile_named};
use deadsync_song_lua::{
    self as song, SongLuaCompileContext,
    rust_engine::{RustSongRuntime, test_support},
};
use std::path::Path;

fn context() -> SongLuaCompileContext {
    SongLuaCompileContext::new(Path::new("."), "Catalog migration")
}
fn execute(runtime: &mut RustSongRuntime, source: &str) -> Vec<Value> {
    runtime
        .vm_mut()
        .execute(&compile_named(source.as_bytes(), b"@/fixture/catalog.lua").unwrap())
        .unwrap_or_else(|e| panic!("{source}\n{e:?}"))
        .to_vec()
}
#[derive(Debug, PartialEq)]
enum Scalar {
    Nil,
    Boolean(bool),
    Number(u64),
    String(Vec<u8>),
}
fn number(n: f64) -> Scalar {
    Scalar::Number(if n.is_nan() {
        f64::NAN.to_bits()
    } else {
        n.to_bits()
    })
}
struct Pair {
    legacy: mlua::Lua,
    rust: RustSongRuntime,
}
impl Pair {
    fn new(context: &SongLuaCompileContext) -> Self {
        let legacy = mlua::Lua::new();
        song::install_default_stdlib_compat(&legacy, &context.song_dir).unwrap();
        song::install_game_state_globals(&legacy, context).unwrap();
        legacy
            .globals()
            .set("SongUtil", song::create_song_util_table(&legacy).unwrap())
            .unwrap();
        legacy
            .globals()
            .set(song::SONG_LUA_SIDE_EFFECT_COUNT_KEY, 0)
            .unwrap();
        test_support::expose_legacy_catalog(&legacy).unwrap();
        let mut rust = RustSongRuntime::new(context).unwrap();
        test_support::expose_catalog(&mut rust).unwrap();
        Self { legacy, rust }
    }
    fn compare(&mut self, source: &str) {
        let expected: mlua::MultiValue = self
            .legacy
            .load(source)
            .eval()
            .unwrap_or_else(|e| panic!("{source}\n{e}"));
        let expected: Vec<_> = expected
            .into_iter()
            .map(|v| match v {
                mlua::Value::Nil => Scalar::Nil,
                mlua::Value::Boolean(b) => Scalar::Boolean(b),
                mlua::Value::Integer(n) => number(n as f64),
                mlua::Value::Number(n) => number(n),
                mlua::Value::String(s) => Scalar::String(s.as_bytes().to_vec()),
                other => panic!("scalar expected: {other:?}"),
            })
            .collect();
        let actual: Vec<_> = execute(&mut self.rust, source)
            .into_iter()
            .map(|v| match v {
                Value::Nil => Scalar::Nil,
                Value::Boolean(b) => Scalar::Boolean(b),
                Value::Number(n) => number(n),
                Value::String(id) => {
                    Scalar::String(self.rust.vm_mut().string_bytes(id).unwrap().to_vec())
                }
                other => panic!("scalar expected: {other:?}"),
            })
            .collect();
        if actual != expected {
            for (a, b) in actual.iter().zip(&expected) {
                if let (Scalar::String(a), Scalar::String(b)) = (a, b) {
                    if a != b {
                        let i = a
                            .iter()
                            .zip(b)
                            .position(|(a, b)| a != b)
                            .unwrap_or(a.len().min(b.len()));
                        panic!(
                            "snapshot mismatch at {i}: actual {:?}, expected {:?}",
                            String::from_utf8_lossy(&a[i.saturating_sub(60)..a.len().min(i + 180)]),
                            String::from_utf8_lossy(&b[i.saturating_sub(60)..b.len().min(i + 180)])
                        );
                    }
                }
            }
            assert_eq!(actual, expected, "{source}");
        }
    }
}

